  add("eng12", "e12-1", 2, [{"type":"regular","q":"What does the suffix '-eth' indicate in Early Modern English?","answer":"Third-person singular present tense (he/she/it)","solution":"'Doth' means 'does' and 'hath' means 'has'; the -eth ending marks singular verb forms."},{"type":"regular","q":"Translate the Early Modern English word 'forsooth' into modern English.","answer":"Indeed, truly, or in truth","solution":"'Forsooth' is an archaic interjection emphasizing sincerity or surprise."},{"type":"regular","q":"What does the word 'prithee' mean in Shakespeare's time?","answer":"Please (or: I pray thee)","solution":"'Prithee' is a contraction of 'pray thee,' used as a polite request."},{"type":"regular","q":"In Early Modern English, what is the difference between 'thee' and 'you'?","answer":"Thee = informal/singular object; you = formal/plural or formal singular","solution":"'Thee' is the objective form of 'thou,' used for intimate or lower-status persons."},{"type":"regular","q":"What does 'marry' mean as an interjection in Early Modern English?","answer":"Indeed, or an exclamation expressing surprise or emphasis","solution":"'Marry' is used to punctuate speech, not to indicate marriage."},{"type":"regular","q":"Translate: 'What ho! Come hither anon.'","answer":"What! Come here soon. (or: Come over here quickly.)","solution":"'What ho' is an exclamation; 'hither' means 'here'; 'anon' means 'soon.'"},{"type":"regular","q":"What is the Early Modern English word 'methinks' used to express?","answer":"It seems to me (or: I think)","solution":"'Methinks' is an archaic verb meaning 'it appears to me.'"},{"type":"regular","q":"How did the Great Vowel Shift affect Early Modern English pronunciation?","answer":"It changed the pronunciation of long vowels, making English sound different from Middle English","solution":"The Great Vowel Shift occurred roughly 1350–1700 and altered vowel sounds significantly."},{"type":"word","q":"Translate: 'Wherefore art thou, Romeo?'","answer":"Why are you, Romeo? (not: Where are you)","solution":"'Wherefore' means 'why,' not 'where'; Juliet questions why Romeo is a Montague."},{"type":"word","q":"What does 'soft' mean when used as an interjection in Early Modern English?","answer":"Wait, hold on, or be quiet","solution":"'Soft' is used to pause action or draw attention, not to describe texture."},{"type":"word","q":"Translate: 'Fie upon you!'","answer":"Shame on you! (or: How disgraceful!)","solution":"'Fie' is an exclamation of disgust or disapproval."},{"type":"word","q":"What is the Early Modern English word 'nay' used to express?","answer":"No","solution":"'Nay' is the archaic negative response, opposite of 'yea.'"},{"type":"word","q":"Translate: 'Prithee, hold thy tongue.'","answer":"Please, be quiet. (or: I beg you, stop talking.)","solution":"'Prithee' = please; 'hold thy tongue' = be silent."},{"type":"word","q":"What does the Early Modern English phrase 'in sooth' mean?","answer":"In truth, truly, or indeed","solution":"'Sooth' means 'truth,' so 'in sooth' affirms the truthfulness of a statement."},{"type":"word","q":"Why is understanding Early Modern English grammar important for reading Shakespeare?","answer":"It clarifies meaning, reveals character relationships (formal vs. informal), and aids comprehension","solution":"Grammar choices like thou/you reveal social dynamics and help readers grasp the text's full meaning."}]);
